import{z as o,x as n,o as l,c as p,q as i,j as r,D as e,d as t,s,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"EUV 掩模台与吸盘","description":"","frontmatter":{"title":"EUV 掩模台与吸盘","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-reticle-chuck.md","filePath":"litho/euv-reticle-chuck.md","lastUpdated":1791063341000}'),d={name:"litho/euv-reticle-chuck.md"};function h(D,a,c,u,m,C){const B=n("Mermaid");return l(),p("div",null,[a[2]||(a[2]=i('<h1 id="euv-掩模台与吸盘" tabindex="-1">EUV 掩模台与吸盘 <a class="header-anchor" href="#euv-掩模台与吸盘" aria-label="Permalink to &quot;EUV 掩模台与吸盘&quot;">​</a></h1><div class="epigraph"><p>反射版在真空里不能靠大气压差吸住。静电吸盘提供夹持，也把背面形貌和热流写成套刻与焦面。</p><footer>—— 对照 ASML 对 EUV 掩模台 / 静电吸盘的公开讨论；Bakshi 系统机械</footer></div><p><a href="/litho/euv-vacuum-contamination">上一课</a>把扫描腔收成干净真空。缺口是掩模怎么在这张真空里定位：没有空气，真空吸盘失效；反射几何还要把热从多层吸走。背面颗粒如何顶起版面，留给<a href="/litho/reticle-backside-particles">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DUV 掩模台可以靠真空沟槽夹持，大气压提供数十牛顿的均匀力。EUV 腔体是真空，这条力没了。量产用静电吸盘（ESC）：电极–介质–掩模背面构成电容，库仑力夹持。力必须够扫描加速度，又不能在背面留下不可恢复的电荷或损伤。掩模是 <a href="/litho/mask-blank-ltem">LTEM</a> 基板加多层，热膨胀和夹持变形直接进套刻。</p><p><span class="marginnote">静电吸盘（ESC）翻译一下：吸盘表面是电极加一层绝缘介质，掩模背面相当于电容的另一块极板，加电后靠静电引力把版「吸」在台子上——原理类似蹭过头发的气球贴墙，只是受控、可重复、可释放。真空里没有大气压可用，它是少数仍成立的夹持手段。</span></p><p>缺口是真空夹持与热–力耦合，不是再讲工件台磁浮。照明和 pellicle 把功率堆在版上，对流几乎为零，吸盘还是主要热沉。夹持不均匀，版面拱起，最佳焦点和放大率一起漂。</p><p><span class="marginnote">EUV 掩模图形在正面多层上；吸盘抓的是背面。正反面的颗粒、划伤和镀膜不对称，都会通过夹持力变成面形。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ESC 分区控制电压，贴合后做面形与温度图。冷却通道在吸盘体内，把吸收的 EUV 和红外带走。与<a href="/litho/euv-maglev-stage">磁浮工件台</a>同步扫描，掩模侧加速度较小但定位公差按倍率放大到硅片。换版：机械手、库、以及 pellicle 框架必须与吸盘密封面兼容，产尘是污染课的掩模侧源。</p><p>计量：版面反射标记看变形，温度传感器看热漂，夹持力/电流看吸盘健康。配方含加电曲线，避免拉弧。氢环境对绝缘介质和电缆是额外约束，材料必须真空与氢双认证。</p><h3 id="热阻路径就是套刻路径" tabindex="-1">热阻路径就是套刻路径 <a class="header-anchor" href="#热阻路径就是套刻路径" aria-label="Permalink to &quot;热阻路径就是套刻路径&quot;">​</a></h3><p>多层吸收 → 基板扩散 → 吸盘冷却液。路径上任何一层接触不良（背面颗粒、氧化、镀膜不均）都会造成局部热点，放大率成斑。剂量爬坡时这张热图跟着变，静态 overlay 表补偿不了。夹持电压提高可以改善接触，也提高击穿和颗粒压入风险，与下一课同一把刀。</p>',13)),(l(),r(A,null,{default:e(()=>[s(B,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20VAC%5B%22%E6%97%A0%E5%A4%A7%E6%B0%94%E5%8E%8B%22%5D%20--%3E%20ESC%5B%22%E9%9D%99%E7%94%B5%E5%90%B8%E7%9B%98%E5%A4%B9%E6%8C%81%22%5D%0A%20%20ESC%20--%3E%20SHAPE%5B%22%E7%89%88%E9%9D%A2%E9%9D%A2%E5%BD%A2%22%5D%0A%20%20HEAT%5B%22EUV%20%E5%90%B8%E6%94%B6%E7%83%AD%22%5D%20--%3E%20ESC%0A%20%20ESC%20--%3E%20OV%5B%22%E5%A5%97%E5%88%BB%20%2F%20%E7%84%A6%E9%9D%A2%22%5D%0A%20%20BS%5B%22%E8%83%8C%E9%9D%A2%E9%A2%97%E7%B2%92%22%5D%20--%3E%20SHAPE%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"静电压力 \\(P\\sim\\varepsilon E^2\\)。电压受击穿限制，间隙被背面颗粒局部撑开时，力塌掉并留下鼓包——下一课的主题。热：多层吸收的能量经基板到吸盘，径向温度梯度造成放大率误差，随扫描占空比变，OPC 静态补偿吃不掉。电荷弛豫使夹持力随时间变，校准周期课的「零点会漂」在掩模台以电压和温度的形式重现。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：静电力随电压平方增长——电压加倍，夹持压力变四倍。听着诱人，但介质击穿电压不会跟着翻倍，间隙里一颗颗粒尖端就能把局部场强顶过阈值，拉一次弧背面就留坑。所以电压是在「吸得稳」与「打穿」之间的一个窄窗里选的。")],-1)),(l(),r(A,null,{default:e(()=>[s(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%9D%99%E7%94%B5%E5%8E%8B%E5%8A%9B%20P%20%E2%89%88%20%CE%B5E%C2%B2%22%5D%20--%3E%20UP%5B%22%E6%8F%90%E9%AB%98%E5%A4%B9%E6%8C%81%E7%94%B5%E5%8E%8B%22%5D%0A%20%20UP%20--%3E%20F1%5B%22%E6%8E%A5%E8%A7%A6%E6%9B%B4%E7%B4%A7%20%E7%83%AD%E9%98%BB%E6%9B%B4%E4%BD%8E%22%5D%0A%20%20UP%20--%3E%20F2%5B%22%E5%87%BB%E7%A9%BF%E6%8B%89%E5%BC%A7%E9%A3%8E%E9%99%A9%E5%8D%87%22%5D%0A%20%20UP%20--%3E%20F3%5B%22%E9%A2%97%E7%B2%92%E5%8E%8B%E5%85%A5%E8%83%8C%E9%9D%A2%E9%A3%8E%E9%99%A9%E5%8D%87%22%5D%0A%20%20UP%20--%3E%20F4%5B%22%E6%AE%8B%E4%BD%99%E7%94%B5%E8%8D%B7%E5%BC%9B%E8%B1%AB%E5%8F%98%E6%85%A2%22%5D%0A%20%20F1%20--%3E%20G%5B%22%E9%9D%A2%E5%BD%A2%E6%9B%B4%E5%B9%B3%20%E5%A5%97%E5%88%BB%E6%9B%B4%E7%A8%B3%22%5D%0A%20%20F2%20--%3E%20H%5B%22%E5%BF%85%E9%A1%BB%E6%94%B6%E5%9C%A8%E5%87%BB%E7%A9%BF%E7%AA%97%E5%86%85%22%5D%0A%20%20F3%20--%3E%20I%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%E9%A2%97%E7%B2%92%E9%A1%B6%E8%B5%B7%E7%9A%84%E5%89%8D%E5%9B%A0%22%5D%0A%20%20F4%20--%3E%20J%5B%22%E5%A4%B9%E6%8C%81%E5%8A%9B%E9%9A%8F%E6%97%B6%E9%97%B4%E6%BC%82%20%E9%9C%80%E9%87%8D%E6%A0%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">不要把浸没机掩模台真空沟槽的维修经验直接搬过来。介质击穿、氢兼容和热阻是新的失效模式。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开背面颗粒的打印与良率，下一课专写。不重写 DUV 掩模库物流。掩模厂如何做背面，属于后一课程，本课只要求扫描机吸盘把背面当光学面的一部分。夹持电压是配方项，换版类型要重资格。出处：ASML EUV reticle stage；Bakshi；真空污染课。</p><p><span class="marginnote">常见误区：以为掩模被「吸住」就万事大吉。吸盘同时是掩模唯一的散热通道——真空中没有空气对流，多层膜吸收的热只能穿过背面接口进冷却液。接触差一点，热就积在版里，放大率和焦点跟着漂。夹持质量与成像质量，是同一个硬件的两面。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>真空里用静电吸盘夹反射掩模，夹持与热沉是同一硬件。</li><li>版面面形进入套刻和焦面；背面状态通过吸盘耦合到正面成像。</li><li>下一课：颗粒夹在吸盘与背面之间会怎样。</li><li>出处：ASML；Bakshi。</li></ul>',6))])}const _=o(d,[["render",h]]);export{P as __pageData,_ as default};
